head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/elw_recv_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

scwin.gBzNo;
scwin.gSuccess;
scwin.gIsuCd;
scwin.gIsurCd;
scwin.gisuAbbrv;
scwin.gisuEngAbbrv;
scwin.gIsuSrtCd;
scwin.vText;
scwin.vListBzTpCd;
scwin.svrGubun = js_svrGubun; //DR전환시
scwin.vScrenID = "ULDSTF05931.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_logicCheck = function(vBzNo) {
    scwin.gBzNo = vBzNo;
    scwin.gSuccess = true;
    if (scwin.vListBzTpCd == '1') {
        //예비,신규상장
        scwin.fn_logicCheckNew();
    } else if (scwin.vListBzTpCd == '2') {
        //추가예비, 추가상장
        scwin.fn_logicCheckAdd();
    }
};
scwin.fn_logicCheckAdd = function() {
    $c.elw.fn_elwaddisu_read_sync(dts_Isu, scwin.gBzNo);
    scwin.gIsuCd = dts_Isu.getCellData(1, "ISU_CD");
    scwin.gIsurCd = dts_Isu.getCellData(1, "ISUR_CD");
    scwin.gisuAbbrv = dts_Isu.getCellData(1, "ISU_KOR_ABBRV");
    scwin.gisuEngAbbrv = dts_Isu.getCellData(1, "ISU_ENG_ABBRV");
    scwin.gIsuSrtCd = dts_Isu.getCellData(1, "ISU_SRT_CD");

    //by nhkw  20190726
    if (scwin.gisuAbbrv.indexOf(scwin.gIsuSrtCd.substring(scwin.gIsuSrtCd.length - 4, scwin.gIsuSrtCd.length)) == -1 ||
        scwin.gisuEngAbbrv.indexOf(scwin.gIsuSrtCd.substring(scwin.gIsuSrtCd.length - 4, scwin.gIsuSrtCd.length)) == -1) {
        scwin.vText = "종목약명의 일련번호와 단축코드가 일치하지 않습니다.";
        scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }
    scwin.fn_MonthDateCheck(dts_Isu.getCellData(1, "EXP_DD"));
    var gApplDd = dts_Isu.getCellData(1, "LIST_BZ_APPL_DD");
    //alert('gApplDd'+gApplDd);
    var gPreMonthExpDd = dts_CheckDate.getCellData(1, "CALND_DD");

    //	if ( parseInt(gApplDd, 10) > parseInt(gPreMonthExpDd, 10) ) {
    //		vText = "신청일이 만기일 1개월이전이 아닙니다.("+dateForm(gApplDd) + ") : (" + dateForm(gPreMonthExpDd)+")";
    //		fn_gridAddRow(gisuAbbrv, vText);
    //	}

    // 추가상장신청예정일이 1개월이 아닌지 체크 수정 jackal_12.06.08
    var gListApplSchdlDd = dts_Isu.getCellData(1, "LIST_APPL_SCHDL_DD");
    if (dts_Isu.getCellData(1, "LIST_BZ_TP_CD") == "004") // 추가 예비심사 청구인 경우만 체크수정

    {
        if (parseInt(gListApplSchdlDd, 10) > parseInt(gPreMonthExpDd, 10)) {
            scwin.vText = "추가상장신청일이 만기일 1개월이전이 아닙니다.(" + scwin.dateForm(gListApplSchdlDd) + ") : (" + scwin.dateForm(gPreMonthExpDd) + ")";
            scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    }
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=ELW_RECV_LOGICCHECK_OUT_RATE_YN_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.lstrcv.select.elw.logiccheck.outrate.condition" + "&{P}param01=" + scwin.gBzNo;
    dts_CheckDate.DataID = encodeURI(url);
    dts_CheckDate.reset();
    if (dts_Isu.getCellData(1, "LIST_BZ_TP_CD") == "004") // 추가 예비심사 청구인 경우만 체크수정

    {
        // 예심청구일 직전영업일에서 당일로 체크 로직 변경
        // jackal_11.03.04
        if (dts_CheckDate.getCellData(1, "OUT_RATE_YN") == 'N') {
            //	vText = "청구일전일 기준 당행종목이 80%이상 매출되지 않았습니다."+dts_CheckDate.NameString(1, "OUT_RATE");
            scwin.vText = "예심 청구일 당일 기준 당해종목이 80%이상 매출되지 않았습니다." + dts_CheckDate.getCellData(1, "OUT_RATE");
            scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    }
    scwin.fn_elwFncCheck();

    /*2009.10.12 ELW 추가상장 접수시 체크로직 추가
    	최초 발행총액(ISU_TOTAMT), 추가발행총액(ADD_ISU_TOTAMT)
    	*/
    if ((dts_Isu.getCellData(1, "ISU_TOTAMT") - dts_Isu.getCellData(1, "ADD_ISU_TOTAMT")) < 0) {
        scwin.vText = "추가발행총액이 신규상장 시 발행총액보다 큽니다.";
        scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }
    //	추가 발행총액이 10억 만인 경우도 체크 jackal_11.03.04
    if (dts_Isu.getCellData(1, "ADD_ISU_TOTAMT") < 1000000000) {
        scwin.vText = "추가발행총액이 10억 미만입니다.";
        scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }
    if (dts_Isu.getCellData(1, "ISU_CD").substring(5, 6) == "1" && dts_Isu.getCellData(1, "ISU_TOTAMT") < 1000000000) {
        /* 30억원에서 10억원 이상으로 완화 2012.12.31 */
        scwin.vText = "발행총액이 10억 미만입니다.";
        scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }

    // 상장제한종목 체크추가 jackal_11.03.04
    scwin.fn_ListLimitIsuAddCheck();
    // KOSPI200 구성종목으로 체크 jackal_11.04.12 추가상장도 체크추가
    scwin.fn_kospi200Check_add(scwin.gBzNo);

    //기초자산이 1(주식)일 경우 1년이내 투자주의종목지정 체크
    if (dts_Isu.getCellData(1, "ISU_CD").substring(5, 6) == "1") {
        scwin.fn_elwInvstgcautnCheck();
    }

    //SrM-000191426_ELW 상장공시시스템 전산개발 요청 by nhkw 20190726 
    if (dts_Isu.getCellData(1, "LIST_BZ_TP_CD") == "005") {
        var url = "";
        url = "/ElwListedReceive.do?method=readElwAddCorrYn&inputMessageId=ELW_ISU_CORR_YN_ADD_RECEIPT_LSTRCV_INOUT";
        url += "&BZ_PROCS_NO=" + scwin.gBzNo;
        url += "&BZ_PROCS_NO=" + scwin.gBzNo;
        dts_CorrYn.DataID = encodeURI(url);
        dts_CorrYn.Reset();
        if (scwin.fn_checkCorrYn() == "X") {
            scwin.vText = "예비심사 승인 종목정보와 신규상장 신청 종목정보가 일치하지 않습니다.";
            scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    }
    //txb_LogicResult.value = "총 "+dts_List.countRow +"종목에서 로직점검이 발생했습니다."

};
scwin.fn_logicCheckNew = function() {
    $c.elw.fn_elwisu_read_sync(dts_Isu, scwin.gBzNo);
    scwin.gIsuCd = dts_Isu.getCellData(1, "ISU_CD");
    scwin.gIsurCd = dts_Isu.getCellData(1, "ISUR_CD");
    scwin.gisuAbbrv = dts_Isu.getCellData(1, "ISU_KOR_ABBRV");
    scwin.gisuEngAbbrv = dts_Isu.getCellData(1, "ISU_ENG_ABBRV");
    scwin.gIsuSrtCd = dts_Isu.getCellData(1, "ISU_SRT_CD");

    //SrM-000191426 by nhkw  20190726
    if (scwin.gisuAbbrv.indexOf(scwin.gIsuSrtCd.substring(scwin.gIsuSrtCd.length - 4, scwin.gIsuSrtCd.length)) == -1 ||
        scwin.gisuEngAbbrv.indexOf(scwin.gIsuSrtCd.substring(scwin.gIsuSrtCd.length - 4, scwin.gIsuSrtCd.length)) == -1) {
        scwin.vText = "종목단축코드와 한글/영문종목약명이 일치하지 않습니다.";
        scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }
    scwin.fn_checkIsuDdAndExpDd(scwin.gIsuCd, scwin.gBzNo);

    //조기종료일 경우  산정발행가액에 제반비용을 더해야 한다.
    //2010.10.08 
    var str = (dts_Isu.getCellData(1, "ISU_PRC") - dts_Isu.getCellData(1, "CALC_ISU_PRC")) / dts_Isu.getCellData(1, "CALC_ISU_PRC") * 100;

    //SrM-000191426_ELW 상장공시시스템 전산개발 요청 by nhkw 20190726  문구 수정
    if (dts_Isu.getCellData(1, "ELW_RGHT_TP_KIND_CD") == "3") {
        //조기종료

        if ((dts_Isu.getCellData(1, "ISU_PRC") - dts_Isu.getCellData(1, "KO_CALC_ISU_PRC")) / dts_Isu.getCellData(1, "KO_CALC_ISU_PRC") * 100 > 20) {
            scwin.vText = "(발행가액-산정발행가액)/(산정발행가액)이 20% 초과했습니다.";
            scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
        if ((dts_Isu.getCellData(1, "ISU_PRC") - dts_Isu.getCellData(1, "KO_CALC_ISU_PRC")) / dts_Isu.getCellData(1, "KO_CALC_ISU_PRC") * 100 < -20) {
            scwin.vText = "(발행가액-산정발행가액)/(산정발행가액)이 (-20%) 미만입니다.";
            scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    } else {
        if ((dts_Isu.getCellData(1, "ISU_PRC") - dts_Isu.getCellData(1, "CALC_ISU_PRC")) / dts_Isu.getCellData(1, "CALC_ISU_PRC") * 100 > 20) {
            scwin.vText = "(발행가액-산정발행가액)/(산정발행가액)이 20% 초과했습니다.";
            scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
        if ((dts_Isu.getCellData(1, "ISU_PRC") - dts_Isu.getCellData(1, "CALC_ISU_PRC")) / dts_Isu.getCellData(1, "CALC_ISU_PRC") * 100 < -20) {
            scwin.vText = "(발행가액-산정발행가액)/(산정발행가액)이 (-20%) 미만입니다.";
            scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    }

    //발행일 /납일일/ 청약일 일치 여부
    if (dts_Isu.getCellData(1, "ISU_DD") != dts_Isu.getCellData(1, "SUBS_DD") ||
        dts_Isu.getCellData(1, "ISU_DD") != dts_Isu.getCellData(1, "PAY_DD")) {
        scwin.vText = "발행일/납일일/청약일 정보가 일치하지 않습니다.";
        scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }
    scwin.fn_HoldyYn('발행일', dts_Isu.getCellData(1, "ISU_DD"));
    scwin.fn_HoldyYn('만기일', dts_Isu.getCellData(1, "EXP_DD"));
    scwin.fn_HoldyYn('행사개시일', dts_Isu.getCellData(1, "EXER_STRT_DD"));
    scwin.fn_HoldyYn('행사종료일', dts_Isu.getCellData(1, "EXER_END_DD"));
    scwin.fn_HoldyYn('최종거래일', dts_Isu.getCellData(1, "ELW_LSTTRD_DD"));
    scwin.fn_HoldyYn('지급일', dts_Isu.getCellData(1, "ELW_PAY_DD"));
    scwin.fn_HoldyYn('청약일', dts_Isu.getCellData(1, "SUBS_DD"));
    scwin.fn_HoldyYn('납입일', dts_Isu.getCellData(1, "PAY_DD"));

    // KOSPI100 구성종목
    // fn_kospi100Check(gBzNo);
    // KOSPI200 구성종목으로 체크 jackal_11.03.04
    scwin.fn_kospi200Check_new(scwin.gBzNo);
    // 상장제한종목 체크추가 jackal_11.03.04
    scwin.fn_ListLimitIsuCheck();
    // 신규상장 예비심사이면 발행일 체크 jackal_11.03.04
    scwin.fn_PreExamIsuDDCheck(scwin.gBzNo);


    //자동권리행사여부
    if (dts_Isu.getCellData(1, "AUTO_EXER_TP_CD") != "A") {
        scwin.vText = "자동권리행사여부가 자동이 아닙니다.";
        scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }

    //중도상환여부
    if (dts_Isu.getCellData(1, "HALFWY_REDMPT_YN") != "N") {
        scwin.vText = "중도상환여부가 NO가 아닙니다.";
        scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }
    //기명
    if (dts_Isu.getCellData(1, "UINSCRIBE_YN") != "N") {
        scwin.vText = "기명/무기명구분이 기명이 아닙니다.";
        scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }

    //표준구분
    /*
    // 조기종료형인 경우에는  표준구분을 로직체크 하지 않음 jackal_ko_10.06.15
    if ( dts_Isu.NameString(1, "ELW_RGHT_TP_KIND_CD") == "3" ) 
    {}
    else
    {
    	if ( dts_Isu.NameString(1, "STD_YN") != "Y" ) {
    		vText = "표준구분이 표준이 아닙니다.";
    		fn_gridAddRow(gisuAbbrv, vText);
    	}
    }
    */
    // 표준구분과 권리형태의 체크를 조기종료 도입에 따라
    // 표준형,조기종료형에 따라 각각 한꺼번에 체크하도록 변경 jackal_ko_10.06.15
    if ((dts_Isu.getCellData(1, "ISU_CD").substring(6, 7) == "1" || dts_Isu.getCellData(1, "ISU_CD").substring(6, 7) == "2")) {
        if ((dts_Isu.getCellData(1, "ISU_CD").substring(6, 7) == "1" || dts_Isu.getCellData(1, "ISU_CD").substring(6, 7) == "2") &&
            (dts_Isu.getCellData(1, "STD_YN") == "Y") &&
            (dts_Isu.getCellData(1, "ELW_RGHT_TP_KIND_CD") == "1")) {

        } else {
            scwin.vText = "표준형 ELW 상품구분에 오류가 있습니다.";
            scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    }
    if ((dts_Isu.getCellData(1, "ISU_CD").substring(6, 7) == "4" || dts_Isu.getCellData(1, "ISU_CD").substring(6, 7) == "5")) {
        if ((dts_Isu.getCellData(1, "ISU_CD").substring(6, 7) == "4" || dts_Isu.getCellData(1, "ISU_CD").substring(6, 7) == "5") &&
            (dts_Isu.getCellData(1, "STD_YN") == "N") &&
            (dts_Isu.getCellData(1, "ELW_RGHT_TP_KIND_CD") == "3")) {

        } else {
            scwin.vText = "조기종료형 ELW 상품구분에 오류가 있습니다.";
            scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    }

    /*
    if ( ( dts_Isu.NameString(1, "ISU_CD").substring(6, 7) == "1" || dts_Isu.NameString(1, "ISU_CD").substring(6, 7) == "2" )  &&
    	 ( dts_Isu.NameString(1, "STD_YN") == "Y" )  && 
    	 ( dts_Isu.NameString(1, "ELW_RGHT_TP_KIND_CD") == "1" )  )
    { 
    }
    else
    {
    	vText = "표준형 ELW 상품구분에 오류가 있습니다.";
    	fn_gridAddRow(gisuAbbrv, vText);
    }
    if ( ( dts_Isu.NameString(1, "ISU_CD").substring(6, 7) == "4" || dts_Isu.NameString(1, "ISU_CD").substring(6, 7) == "5" )  &&
    	 ( dts_Isu.NameString(1, "STD_YN") == "N" )  && 
    	 ( dts_Isu.NameString(1, "ELW_RGHT_TP_KIND_CD") == "3" )  )
    { }
    else
    {
    	vText = "조기종료형 ELW 상품구분에 오류가 있습니다.";
    	fn_gridAddRow(gisuAbbrv, vText);
    }
    */
    //예탁기관
    //SrM-000191426_ELW 상장공시시스템 전산개발 요청 by nhkw 20190726 증권-> 한국
    if (dts_Isu.getCellData(1, "DEPO_INST_CD") == "" || dts_Isu.getCellData(1, "DEPO_INST_CD") != "9109") {
        scwin.vText = "예탁기관이 한국예탁결제원이 아닙니다.";
        scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }

    //호가스프레드
    if (dts_Isu.getCellData(1, "ORD_SPD_RTO") == "" || dts_Isu.getCellData(1, "ORD_SPD_RTO") != 15) {
        scwin.vText = "호가스프레드가 15가 아닙니다.";
        scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }

    //권리형태
    /*
    // 조기종료형과  비표준 인 경우에는  표준구분을 로직체크 하지 않음 jackal_ko_10.06.15
    if ( dts_Isu.NameString(1, "ELW_RGHT_TP_KIND_CD") == "3"  &&  dts_Isu.NameString(1, "STD_YN") == "N"  ) 
    {}
    else
    {
    	if ( dts_Isu.NameString(1, "ELW_RGHT_TP_KIND_CD") != "1" ) {
    		vText = "권리형태가 표준형이 아닙니다.";
    		fn_gridAddRow(gisuAbbrv, vText);
    	} 
    }
    */

    if (dts_Isu.getCellData(1, "ELW_RGHT_TP_KIND_CD") == "2" && dts_Isu.getCellData(1, "ELW_FINAL_PAY_VAL") == "") {
        scwin.vText = "권리형태가 디지털형이면 확정지급액값이 필요합니다. 확정지급액을 확인바랍니다.";
        scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
    } else {
        if (dts_Isu.getCellData(1, "ELW_FINAL_PAY_VAL") != "" && dts_Isu.getCellData(1, "ELW_FINAL_PAY_VAL") != "0") {
