            }
        }

        // 수정 2014.10.31 기초자산이주가지수이면서 기준가격결정일이 예심청구일 2주 전인지 체크
        if (dts_Isu.getCellData(1, "LIST_BZ_TP_CD") == "002" && dts_Isu.getCellData(1, "ELW_ULY_BAS_PRC_DECSN_14DD_YN") == "Y") {
            scwin.vText = "기준가격결정일이 예비심사청구일 전 2주 이내의 날이 아닙니다.";
            scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    }
    if (dts_Isu.getCellData(1, "ISU_CD").substring(5, 6) == "1") // 기초자산이 주식이면 

    {
        // 추가 2014.10.31(기초자산이 주식인 경우, 기준가격 결정일이 가장최근 최종거래일의 전주  금요일인지 체크(보통 매달 첫째주 금요일))
        scwin.fn_FbasprcDecsnDayCheck();

        // 추가 2014.10.31 (기조차산이 주식인경우,해당 기준가격 범위의 전환비율이 아닌경우 체크)
        /*
        	 10,000 이하 : 0.1
        	 10,000초과 ~ 20,000이하:0.05
        	 20,000초과 ~ 50,000이하:0.02
        	 50,000초과~ 100,000이하:0.01
        	100,000초과~ 200,000이하:0.005
        	200,000초과~ 500,000이하:0.002
        	500,000초과:  0.001
        */
        if (dts_Isu.getCellData(1, "CONV_RTO_YN") == "Y") {
            scwin.vText = "기준가격(" + $c.stf.addComma(dts_Isu.getCellData(1, "ELW_ULY_BAS_PRC")) + ")에 해당하는 전환비율(" + dts_Isu.getCellData(1, "ELW_CONV_RTO") + ")이 일치하지 않습니다.";
            scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
        if (dts_Isu.getCellData(1, "PERITY_RT") >= 110) {
            scwin.fn_elwBasPerityCheck110();
        } else {
            // 추가 2014.10.31 주식ELW 행사가격이 기준 패리티로부터 산출된 값인지 체크
            scwin.fn_elwBasPerityCheck();
        }
    }

    // 수정 2014.10.31 극외가격 90 % 미만 체크
    // 극외가격 85 % 미만 체크 jackal_11.06.10
    if (dts_Isu.getCellData(1, "PERITY_90RT_YN") == "Y") {
        scwin.vText = "패리티가 90% 미만입니다.";
        scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }



    //기초자산이 1(주식)일 경우 1년이내 투자주의종목지정 체크
    if (dts_Isu.getCellData(1, "ISU_CD").substring(5, 6) == "1") {
        scwin.fn_elwInvstgcautnCheck();
    }

    // 기초자산별 역사적변동성 산출 후 적용변동성 체크
    scwin.fn_HistVoltCheck();

    // 기초자산이 주식인데 기초주권명이 공란인 경우 jackal_150622
    if (dts_Isu.getCellData(1, "ISU_CD").substring(5, 6) == "1") // 기초자산이 주식이면 

    {
        $c.elw.fn_elwUly_read_sync(dts_UlyIsu, scwin.gBzNo);
        if (dts_UlyIsu.getCellData(1, "ULY_ISU_NM") == "") {
            scwin.vText = "기초자산이 주식인데 기초주권명이 공란입니다.";
            scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    }

    //SrM-000191426_ELW 상장공시시스템 전산개발 요청 by nhkw 20190726 
    if (dts_Isu.getCellData(1, "LIST_BZ_TP_CD") == "003" || dts_Isu.getCellData(1, "LIST_BZ_TP_CD") == "005") {
        var url = "";
        url = "/ElwListedReceive.do?method=readElwCorrYn&inputMessageId=ELW_ISU_CORR_YN_RECEIPT_LSTRCV_INOUT";
        url += "&BZ_PROCS_NO=" + scwin.gBzNo;
        url += "&BZ_PROCS_NO=" + scwin.gBzNo;
        dts_CorrYn.DataID = encodeURI(url);
        dts_CorrYn.Reset();
        if (scwin.fn_checkCorrYn() == "X") {
            scwin.vText = "예비심사 승인 종목정보와 신규상장 신청 종목정보가 일치하지 않습니다.";
            scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    }
    txb_LogicResult.setValue("총 " + dts_List.getTotalRow() + "종목에서 로직점검이 발생했습니다.");
};
scwin.fn_checkCorrYn = function() {
    var isCorryn = "X";
    for (var j = 1; j <= dts_CorrYn.getTotalCol(); j++) {
        if (dts_CorrYn.getCellData(1, dts_CorrYn.getColumnID(j - 1)) != dts_CorrYn.getCellData(2, dts_CorrYn.getColumnID(j - 1))) {
            isCorryn = "X";
            break;
        }
        isCorryn = "O";
    }
    return isCorryn;
};
scwin.fn_elwInvstgcautnCheck = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=ELW_RECV_LOGICCHECK_INVSTGCAUNT_ISU_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.lstrcv.select.elw.isu.receipt.invstgcautn.condition" + "&{P}param01=" + scwin.gBzNo + "&{P}param02=" + scwin.gBzNo;
    dts_invstgCautn.DataID = encodeURI(url);
    dts_invstgCautn.reset();
    var outText = '';
    for (var idx = 1; idx <= dts_invstgCautn.getTotalRow(); idx++) {
        var comNm = dts_invstgCautn.getCellData(idx, "INVSTCAUTN_ISU_COM_NM");
        var procDate = dts_invstgCautn.getCellData(idx, "INVSTCAUTN_ISU_PROC_DATE");
        var procFormNm = dts_invstgCautn.getCellData(idx, "FORM_KOR_NM");

        //outText += "회사명: " + comNm + " 처리일: " + procDate + " " ;
        outText += "'" + comNm + "'은 " + procDate + "에";
    }
    if (outText != '') {
        scwin.vText = "해당 기초자산 " + outText + " " + procFormNm + "으로 되었습니다.";
        scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }
};
