scwin.fn_JongGaCheck = function(vJisuGubun, vDeciStdDt, vStdPrc) {
    if (vJisuGubun == "3") // 기초자산이 주가지수이면 

    {
        var url = "";
        if (dts_Isu.getCellData(1, "ELW_OBJ_IDX_TP_CD") == "5") {
            //	KOSDAQ150
            url = "/listingCommon.do?method=listGeneral&outputMessageId=ELW_RECV_LOGICCHECK_JISU_CLS_PRC_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.lstrcv.select.elw.logiccheck.jisucls.condition" + "&{P}param01=" + "Q5G01P" + //Q5G01P  2 203
                "&{P}param02=" + vDeciStdDt;
            dts_CheckDate.DataID = encodeURI(url);
            dts_CheckDate.reset();
        } else if (dts_Isu.getCellData(1, "ELW_OBJ_IDX_TP_CD") == "1") {
            // 코스피200
            url = "/listingCommon.do?method=listGeneral&outputMessageId=ELW_RECV_LOGICCHECK_JISU_CLS_PRC_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.lstrcv.select.elw.logiccheck.jisucls.condition" + "&{P}param01=" + "K2G01P" + // K2G01P 1 028
                "&{P}param02=" + vDeciStdDt;
            dts_CheckDate.DataID = encodeURI(url);
            dts_CheckDate.reset();
        } else {
            //	나머지는 ...
            url = "/listingCommon.do?method=listGeneral&outputMessageId=ELW_RECV_LOGICCHECK_JISU_CLS_PRC_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.lstrcv.select.elw.logiccheck.jisucls.condition" + "&{P}param01=" + "K2G01P" + // K2G01P 1 028
                "&{P}param02=" + vDeciStdDt;
            dts_CheckDate.DataID = encodeURI(url);
            dts_CheckDate.reset();
        }


        // 주가지수일경우  종가 체크
        var gJisuPrc = dts_CheckDate.getCellData(1, "ELW_JISU_CLS_PRC");
        if (gJisuPrc != vStdPrc) {
            scwin.vText = "해당일의 기준가격 정보가 일치하지 않습니다 : " + vDeciStdDt + " 종가 " + gJisuPrc;
            scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    } else

    // 기초자산이 주식이면 

    {
        var url = "/listingCommon.do?method=listGeneral&outputMessageId=ELW_RECV_LOGICCHECK_JUSIK_CLS_PRC_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.lstrcv.select.elw.logiccheck.jusikcls.condition" + "&{P}param01=" + scwin.gBzNo + "&{P}param02=" + vDeciStdDt;
        dts_CheckDate.DataID = encodeURI(url);
        dts_CheckDate.reset();

        // 주가지수일경우  종가 체크
        var gJisuPrc = dts_CheckDate.getCellData(1, "ELW_JUSIK_CLS_PRC");
        if (gJisuPrc != vStdPrc) {
            scwin.vText = "해당일의 기준가격 정보가 일치하지 않습니다 : " + vDeciStdDt + " 종가 " + gJisuPrc;
            scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    }
};




// 조기종료 관련 체크 로직 함수 jackal 10.06.15
scwin.fn_KnockOutCheck = function() {
    // 절대값 체크해야 함.
    // 1.조기종료발생기준가격과 권리행사가격의 차이가 기준가격대비 5%미만인 경우
    if (dts_Isu.getCellData(1, "OCC_EXER_BAS_PRC_PERCENT_5") == "Y") {
        scwin.vText = "조기종료발생기준가격과 권리행사가격의 차이가 기준가격대비 5%미만  입니다.";
        scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }
    /*
    if ( (dts_Isu.NameString(1, "ELW_RGHT_TP_CD")  == "C" )  && 
        ( (dts_Isu.NameString(1, "ELW_KO_OCCR_BAS_PRC") -  dts_Isu.NameString(1, "ELW_EXER_PRC")) / dts_Isu.NameString(1, "ELW_ULY_BAS_PRC") *100 < 5  ) )
    {
    		vText = "조기종료발생기준가격과 권리행사가격의 차이가 기준가격대비 5%미만  입니다.";
    		fn_gridAddRow(gisuAbbrv, vText);
    }
    else if ( (dts_Isu.NameString(1, "ELW_RGHT_TP_CD")  == "P" )  && 
        ( (dts_Isu.NameString(1, "ELW_EXER_PRC") - dts_Isu.NameString(1, "ELW_KO_OCCR_BAS_PRC") ) / dts_Isu.NameString(1, "ELW_ULY_BAS_PRC") *100 < 5  ) )
    {
    		vText = "조기종료발생기준가격과 권리행사가격의 차이가 기준가격대비 5%미만  입니다.";
    		fn_gridAddRow(gisuAbbrv, vText);
    }
    */

    // 2.권리유형이 조기종료형인데 권리내용분류코드가 4또는 5가 아닌 경우
    if (dts_Isu.getCellData(1, "ISU_CD").substring(6, 7) == "4" || dts_Isu.getCellData(1, "ISU_CD").substring(6, 7) == "5") {

    } else {
        scwin.vText = "권리유형이 조기종료형인데 권리내용분류코드가 4또는 5가 아닙니다.";
        scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }
    // 3.권리유형이 조기종료형인데 한글종목명 및 한글종목약명에 '조기종료' 가 포함되지 않은 경우
    if (dts_Isu.getCellData(1, "ISU_KOR_NM").indexOf("조기종료") < 0 || dts_Isu.getCellData(1, "ISU_KOR_ABBRV").indexOf("조기종료") < 0) {
        scwin.vText = "권리유형이 조기종료형인데 한글종목명 및 한글종목약명에 '조기종료' 가 포함되어   있지 않습니다.";
        scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }
    // 4.권리유형이 조기종료형인데 영문종목명 및 영문종목약명에 각각 'KNOCK-OUT', 'KO' 가 포함되지 않은 경우
    if (dts_Isu.getCellData(1, "ISU_ENG_NM").indexOf("KNOCK-OUT") < 0 || dts_Isu.getCellData(1, "ISU_ENG_ABBRV").indexOf("KO") < 0) {
        scwin.vText = "권리유형이 조기종료형인데 영문종목명 및 영문종목약명에 각각 'KNOCK-OUT', 'KO' 가 포함되어 있지 않습니다.";
        scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }
    // 5.권리행사유형이 조기종료형인데 발행총액이 30억원 미만인 경우
    if (dts_Isu.getCellData(1, "ISU_TOTAMT") < 1000000000) /*30억에서 10억으로 수정 20121231*/ {
        scwin.vText = "권리행사유형이 조기종료형인데 발행총액이 10억원 미만입니다.";
        scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }
    // 6.권리행사유형이 조기종료형인데 조기종료발생기준가격이 공란인 경우
    if (dts_Isu.getCellData(1, "ELW_KO_OCCR_BAS_PRC") == 0) {
        scwin.vText = "권리행사유형이 조기종료형인데 조기종료발생기준가격이 없습니다.";
        scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }
    // 8.권리유형이 콜일때 조기종료 발생기준가격이 권리행사가격 이하인 경우
    if (dts_Isu.getCellData(1, "ELW_RGHT_TP_CD") == "C") {
        if ((dts_Isu.getCellData(1, "ELW_KO_OCCR_BAS_PRC") - dts_Isu.getCellData(1, "ELW_EXER_PRC")) <= 0) {
            scwin.vText = "권리유형이 콜일때 조기종료 발생기준가격이 권리행사가격 이하로 지정되어 있습니다.";
            scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
        // 9.권리유형이 콜일때 기준가격이 조기종료 발생기준가격이 이하인 경우
        if ((dts_Isu.getCellData(1, "ELW_ULY_BAS_PRC") - dts_Isu.getCellData(1, "ELW_KO_OCCR_BAS_PRC")) <= 0) {
            scwin.vText = "권리유형이 콜일때 기준가격이 조기종료 발생기준가격이 이하로 지정되어 있습니다.";
            scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    }
    // 10.권리유형이 풋일때 조기종료 발생기준가격이 권리행사가격 이상인 경우
    if (dts_Isu.getCellData(1, "ELW_RGHT_TP_CD") == "P") {
        if ((dts_Isu.getCellData(1, "ELW_KO_OCCR_BAS_PRC") - dts_Isu.getCellData(1, "ELW_EXER_PRC")) >= 0) {
            scwin.vText = "권리유형이 풋일때 조기종료 발생기준가격이 권리행사가격 이상으로 지정되어 있습니다.";
            scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
        // 11.권리유형이 풋일때 기준가격이 조기종료 발생기준가격이 이상인 경우
        if ((dts_Isu.getCellData(1, "ELW_ULY_BAS_PRC") - dts_Isu.getCellData(1, "ELW_KO_OCCR_BAS_PRC")) >= 0) {
            scwin.vText = "권리유형이 풋일때 기준가격이 조기종료 발생기준가격이 이상으로 지정되어 있습니다.";
            scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    }
};
