scwin.dateForm = function(pStr) {
    var str = pStr.substring(0, 4) + "년" + pStr.substring(4, 6) + "월" + pStr.substring(6, 8) + "일";
    return str;
};



/**
 *  입력한일자가 영업일인지 체크
 * fn_HoldyYn
 */
scwin.fn_HoldyYn = function(vStrItem, vStrDD) {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=ELW_RECV_LOGICCHECK_COUNT_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.lstrcv.select.elw.logiccheck.holdyyn.condition" + "&{P}param01=" + vStrDD;
    dts_CheckDate.DataID = encodeURI(url);
    dts_CheckDate.reset();
    var gCnt = dts_CheckDate.getCellData(1, "CNT");
    if (gCnt < 1) {
        scwin.vText = vStrItem + "은 매매일이 아닙니다.(" + scwin.dateForm(vStrDD) + ")";
        scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }
};





