 */
scwin.fn_checkIsuDdAndExpDd = function(vIsuCd, vBzNo) {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=ELW_RECV_LOGICCHECK_DATE_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.lstrcv.select.elw.logiccheck.date.listisudd.condition" + "&{P}param01=" + vIsuCd + "&{P}param02=" + vBzNo;
    dts_CheckDate.DataID = encodeURI(url);
    dts_CheckDate.reset();
    var vIsuDd_ExpDd_Between = dts_CheckDate.getCellData(1, "ISU_BETWEEN");
    if (vIsuDd_ExpDd_Between != "" && vIsuDd_ExpDd_Between != 0) {
        if (vIsuDd_ExpDd_Between <= 3) {
            scwin.vText = "만기일과 발행일의 차이가 3개월 이하입니다.";
            scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
        if (vIsuDd_ExpDd_Between >= 12) {
            scwin.vText = "만기일과 발행일의 차이가 12개월 이상입니다.";
            scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    }
};




/**
 *  신규상장 예비심사시 발행일 체크 추가
 *  예비심사 청구일 기준으로 발행일이 과거날자인 경우 체크 (오늘 이상이어야 함)
 */
scwin.fn_PreExamIsuDDCheck = function(vBzNo) {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=ELW_RECV_LOGICCHECK_COUNT_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.lstrcv.select.elw.logiccheck.newpreexamyn.condition" + "&{P}param01=" + vBzNo;
    dts_CheckDate.DataID = encodeURI(url);
    dts_CheckDate.reset();
    var gCnt = dts_CheckDate.getCellData(1, "CNT");
    //alert('gCnt'+gCnt);
    if (gCnt == 1) // 신규상장 예비심사인 경우 

    {
        // 발행일 체크 
        url = "/listingCommon.do?method=listGeneral&outputMessageId=ELW_RECV_LOGICCHECK_NEWPREEXAM_ISUDD_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.lstrcv.select.elw.logiccheck.newpreexamynisudd.condition" + "&{P}param01=" + vBzNo;
        dts_CheckDate.DataID = encodeURI(url);
        dts_CheckDate.reset();
        gCnt = dts_CheckDate.getCellData(1, "ISU_DD");
        if (gCnt != "Y") // 발행일은 신청일보다 커야 합니다.

        {
            scwin.vText = "발행일(" + gCnt + ")은 예비심사신청일 이후의 날자이어야 합니다.";
            scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    }
};





