 *  KOSPI100 구성종목
 */
scwin.fn_kospi100Check = function(vBzNo) {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=ELW_RECV_LOGICCHECK_COUNT_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.lstrcv.select.elw.logiccheck.kospi100.condition" + "&{P}param01=" + vBzNo;
    dts_CheckDate.DataID = encodeURI(url);
    dts_CheckDate.reset();
    var gFncUlyTpCd = dts_Isu.getCellData(1, "FNC_ULY_TP_CD");
    var gCnt = dts_CheckDate.getCellData(1, "CNT");
    //alert('gCnt'+gCnt);
    if (gFncUlyTpCd == 1 && gCnt < 1) {
        scwin.vText = "기초자산이 KOSPI100 구성종목이 아닙니다.";
        scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }
    if (gCnt > 1) {
        scwin.vText = "기초자산이 1개 이상입니다.";
        scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }
};



