/**
 *  2013.03.08 madbaram
 *  기초자산별 역사적변동성 산출 후 적용변동성 체크 
 */
scwin.fn_HistVoltCheck = function() {
    var url = "";
    if (dts_Isu.getCellData(1, "ELW_OBJ_IDX_TP_CD") == "1") {
        //기초지수가 KOSPI200일 경우
        url = "/listingCommon.do?method=listGeneralForDynamicName&outputMessageId=ELW_RECV_LOGICCHECK_HIST_VOLT_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.lstrcv.select.elw.idx.logiccheck.histvolt.condition" + "&{P}V_IDX_ID=" + "K2G01P" + // KOSPI200 1 028 jackal_23.01.01
            "&{P}V_APPL_DD=" + dts_Isu.getCellData(1, "APPL_DD");
    } else if (dts_Isu.getCellData(1, "ELW_OBJ_IDX_TP_CD") == "5") {
        //기초지수가 KOSDAQ150일 경우
        url = "/listingCommon.do?method=listGeneralForDynamicName&outputMessageId=ELW_RECV_LOGICCHECK_HIST_VOLT_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.lstrcv.select.elw.idx.logiccheck.histvolt.condition" + "&{P}V_IDX_ID=" + "Q5G01P" + // KOSDAQ150 2 203 jackal_23.01.01
            "&{P}V_APPL_DD=" + dts_Isu.getCellData(1, "APPL_DD");
    } else {
        url = "/listingCommon.do?method=listGeneralForDynamicName&outputMessageId=ELW_RECV_LOGICCHECK_HIST_VOLT_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.lstrcv.select.elw.logiccheck.histvolt.condition" + "&{P}ISU_CD=" + dts_Isu.getCellData(1, "ULY_ISU_CD") + "&{P}APPL_DD=" + dts_Isu.getCellData(1, "APPL_DD");
    }
    dts_HistVolt.DataID = encodeURI(url);
    dts_HistVolt.reset();
    var gMaxHistVolt = dts_HistVolt.getCellData(1, "MAX_HIST_VOLT");
    var gApplVoltRto = dts_Isu.getCellData(1, "APPL_VOLT_RTO");

    //alert("gMaxHistVolt:"+gMaxHistVolt + " gApplVoltRto:" +gApplVoltRto + " (gMaxHistVolt * 2) :" + (gMaxHistVolt * 2) );
    if (gApplVoltRto - (gMaxHistVolt * 2) > 0) {
        scwin.vText = "적용변동성이 역사적변동성의 2배를 초과하였습니다. (역사적변동성:" + gMaxHistVolt + ")";
        scwin.fn_gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }
};
scwin.fn_gridAddRow = function(gIsuAbbrv, pStr) {
    dts_List.insertRow();
    dts_List.setCellData(dts_List.getTotalRow(), "ISU_KOR_NM", gIsuAbbrv);
    dts_List.setCellData(dts_List.getTotalRow(), "DATA", pStr);
    scwin.gSuccess = false;
};
scwin.fn_logicCheckServerMulti = function() {
    var parentWin = $c.frame.path("../");
    var dtsObj = parentWin.fn_getDataSet();
    var vListBzTpCd = parentWin.MaxTab_01.getSelectedTabIndex();
    $c.stf.CopyDataSet(dtsObj, dts_Logic, "resetStatus=no");
    trs_Logic2.Action = $c.lc.fn_encodeNSession("/ElwListedReceive.do?method=elwLogicSave&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&USER_ID=" + js_id + "&LIST_BZ_TP_CD=" + scwin.vListBzTpCd);
    trs_Logic2.KeyName = "toinb_dataid4";
    trs_Logic2.KeyValue = "JSP(I:pInput=dts_Logic,O:pOutput=dts_List2)";
    trs_Logic2.Post();
    var currTime = dts_List2.getCellData(1, "DATA");
    var url = "/ElwListedReceive.do?method=elwLogicSelect&inputMessageId=ELW_LOGIC_CHECK_RESULT";
    url += "&CURR_TIME=" + currTime;
    url += "&LIST_BZ_TP_CD=" + scwin.vListBzTpCd;
    url += "&USER_ID=" + js_id;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_List);
};
scwin.fn_logicCheckServerSingle = function(bzProcsNo, listBzTpCd) {
    var url = "/ElwListedReceive.do?method=elwLogicSingle&inputMessageId=ELW_LOGIC_CHECK_RESULT";
    url += "&BZ_PROCS_NO=" + bzProcsNo;
    url += "&LIST_BZ_TP_CD=" + listBzTpCd;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_List);
};
scwin.resetLogicChecked = function() {
    var parentWin = $c.frame.path("../");
    if (parentWin.logicPackYn == 'Y') {
        var dtsObj = parentWin.fn_getDataSet();
        for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
            if (dtsObj.getCellData(i, "CHECK") == "T") {
                var isuKorNm = dtsObj.getCellData(i, "ISU_KOR_ABBRV");
                var Row = $c.cp.getNameValueRow(dts_List, "ISU_KOR_NM", isuKorNm);
                if (Row <= 0) {
                    dtsObj.setCellData(i, "CHECK", "F");
                }
            }
        }
    }
};
