scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    var parentWin = $c.frame.path("../");
    var vHeadString = "NO:STRING(20),ISU_KOR_NM:STRING(200),DATA:STRING(500)";
    var faultCount = 0;
    //dts_List.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 

    // ------------------------------------------- 여기까지 공통 ---------------------------------------------
    // ------------------------------------------- 서버로직 -------------------------------------
    if (parentWin.logicPackYn == 'N') {
        scwin.fn_logicCheckServerSingle(parentWin.vBzProcsNo, parentWin.logicBizTyp);
    } else if (parentWin.logicPackYn == 'Y') {
        scwin.fn_logicCheckServerMulti();
        if (scwin.vListBzTpCd == '1') {
            //예비,신규상장
            parentWin.grd_List_1.setBroadcast(true);
        } else if (scwin.vListBzTpCd == '2') {
            //추가예비, 추가상장
            parentWin.grd_List_2.setBroadcast(true);
        }
    }
    // ------------------------------------------- 서버로직 -------------------------------------

};
